#!/bin/sh
# generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
# PostToolUse hook (Edit|Write): после правки файла возвращает в контекст напоминание о гейтах
# качества для его типа. Не блокирует (всегда exit 0). Вывод — JSON с additionalContext:
# stdout PostToolUse в контекст модели сам по себе не попадает, только через это поле.
#
# Гейты проекта — не в этом файле, а в .claude/quality-gates.txt (путь можно передать
# первым аргументом): копия хука обязана совпадать с шаблоном плагина байт в байт,
# поэтому всё проектное живёт рядом, и update его не трогает. Формат файла:
#
#   # комментарий; пустые строки пропускаются
#   <маска> <текст гейта>
#
# Маска — шаблон shell `case` по пути файла с прямыми слэшами (`*` захватывает и `/`,
# альтернативы — через `|` без пробелов: `*.vue|*.ts`),
# текст — остаток строки после первого пробела. Срабатывает первая подходящая строка,
# поэтому частные маски ставятся выше общих:
#
#   */database/migrations/*.php  Миграция: идемпотентность, индекс на FK, …
#   *.php                        PHP: статанализ, затем полный check.
#
# Нет файла или ни одна маска не подошла — хук молчит.

cd "${CLAUDE_PROJECT_DIR:-.}" 2>/dev/null || exit 0

RULES="${1:-.claude/quality-gates.txt}"
[ -f "$RULES" ] || exit 0

input=$(cat)

# file_path из payload'а инструмента; sed вместо jq — jq в окружении может не быть
file=$(printf '%s' "$input" | sed -n 's/.*"file_path"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n 1)

[ -z "$file" ] && exit 0

# На Windows путь приходит с обратными слэшами, JSON-экранированными в `\\`: без замены
# и сжатия маски с `/` не совпали бы ни с одним путём.
norm=$(printf '%s' "$file" | tr '\\' '/' | tr -s '/')

msg=""
while IFS= read -r line || [ -n "$line" ]; do
  line=$(printf '%s' "$line" | tr -d '\r')
  case "$line" in
    ''|'#'*) continue ;;
  esac
  mask=${line%%[[:space:]]*}
  text=${line#"$mask"}
  text=$(printf '%s' "$text" | sed 's/^[[:space:]]*//')
  [ -n "$text" ] || continue
  # Маска без кавычек — намеренно: так case читает её как шаблон, а не как литерал.
  # `|` из переменной case не разбирает как альтернативу — режем маску сами.
  hit=0
  rest=$mask
  while [ -n "$rest" ]; do
    alt=${rest%%|*}
    case "$rest" in *'|'*) rest=${rest#*|} ;; *) rest='' ;; esac
    case "$norm" in
      $alt) hit=1; break ;;
    esac
  done
  if [ "$hit" = 1 ]; then
    msg=$text
    break
  fi
done < "$RULES"

[ -z "$msg" ] && exit 0

msg=$(printf '%s' "$msg" | sed 's/\\/\\\\/g; s/"/\\"/g')

printf '{"hookSpecificOutput":{"hookEventName":"PostToolUse","additionalContext":"%s"}}\n' "$msg"
exit 0
